import { OneKeyLocalError } from '@onekeyhq/shared/src/errors';
import type { IServerNetwork } from '@onekeyhq/shared/types';
import type {
  IWalletAddedEventParams,
  IWalletStartedParams,
} from '@onekeyhq/shared/types/analytics/onboarding';

import { BaseScene } from '../../../base/baseScene';
import { LogToLocal, LogToServer } from '../../../base/decorators';

interface IToken {
  network: string;
  tokenSymbol: string;
  tokenAddress: string;
}

export type IHomePageViewedState =
  | 'notBackedUp'
  | 'emptyWallet'
  | 'fundedWallet';

export class WalletScene extends BaseScene {
  @LogToServer()
  @LogToLocal()
  public addWalletStarted(params: IWalletStartedParams) {
    switch (params.addMethod) {
      case 'CreateWallet':
        return {
          addMethod: 'CreateWallet',
          isSoftwareWalletOnlyUser: params.isSoftwareWalletOnlyUser,
          details: {
            unbackedUp: params.details.unbackedUp,
          },
        };

      case 'ImportWallet':
        return {
          addMethod: 'ImportWallet',
          isSoftwareWalletOnlyUser: params.isSoftwareWalletOnlyUser,
          details: {
            importType: params.details.importType,
          },
        };

      case 'ConnectHWWallet':
        return {
          addMethod: 'ConnectHWWallet',
          isSoftwareWalletOnlyUser: params.isSoftwareWalletOnlyUser,
          details: {
            communication: params.details.communication,
            hardwareWalletType: params.details.hardwareWalletType,
            ...(params.details.vendor && { vendor: params.details.vendor }),
          },
        };

      case 'Connect3rdPartyWallet':
        return {
          addMethod: 'Connect3rdPartyWallet',
          isSoftwareWalletOnlyUser: params.isSoftwareWalletOnlyUser,
          details: {
            protocol: params.details.protocol,
            network: params.details.network,
            walletName: params.details.walletName,
          },
        };

      case 'CreateKeylessWallet':
        return {
          addMethod: 'CreateKeylessWallet',
          isSoftwareWalletOnlyUser: params.isSoftwareWalletOnlyUser,
          details: {
            provider: params.details.provider,
          },
        };

      default: {
        const _exhaustiveCheck: never = params;
        throw new OneKeyLocalError(
          `Unreachable case: ${JSON.stringify(_exhaustiveCheck)}`,
        );
      }
    }
  }

  @LogToServer()
  @LogToLocal()
  public walletAdded(params: IWalletAddedEventParams) {
    switch (params.addMethod) {
      case 'CreateWallet':
        return {
          status: params.status,
          addMethod: 'CreateWallet',
          isSoftwareWalletOnlyUser: params.isSoftwareWalletOnlyUser,
          details: {
            isBiometricSet: params.details.isBiometricSet,
            unbackedUp: params.details.unbackedUp,
          },
        };

      case 'ImportWallet':
        return {
          status: params.status,
          addMethod: 'ImportWallet',
          isSoftwareWalletOnlyUser: params.isSoftwareWalletOnlyUser,
          details: {
            importType: params.details.importType,
          },
        };

      case 'ConnectHWWallet':
        return {
          status: params.status,
          addMethod: 'ConnectHardware',
          isSoftwareWalletOnlyUser: params.isSoftwareWalletOnlyUser,
          details: {
            communication: params.details.communication,
            deviceType: params.details.deviceType,
            hardwareWalletType: params.details.hardwareWalletType,
            ...(params.details.vendor && { vendor: params.details.vendor }),
            ...(params.details.firmwareVersions && {
              firmwareVersions: params.details.firmwareVersions,
            }),
          },
        };

      case 'Connect3rdPartyWallet':
        return {
          status: params.status,
          addMethod: 'Connect3rdPartyWallet',
          isSoftwareWalletOnlyUser: params.isSoftwareWalletOnlyUser,
          details: {
            protocol: params.details.protocol,
            network: params.details.network,
            ...(params.details.walletName && {
              walletName: params.details.walletName,
            }),
          },
        };

      case 'CreateKeylessWallet':
        return {
          status: params.status,
          addMethod: 'CreateKeylessWallet',
          isSoftwareWalletOnlyUser: params.isSoftwareWalletOnlyUser,
          details: {
            provider: params.details.provider,
          },
        };

      default: {
        const _exhaustiveCheck: never = params;
        throw new OneKeyLocalError(
          `Unreachable case: ${JSON.stringify(_exhaustiveCheck)}`,
        );
      }
    }
  }

  @LogToServer()
  @LogToLocal()
  public onboard(params: {
    onboardMethod:
      | 'createWallet'
      | 'importWallet'
      | 'connectHWWallet'
      | 'connect3rdPartyWallet'
      | 'createKeylessWallet';
  }) {
    return params;
  }

  @LogToServer()
  @LogToLocal()
  public deleteWallet() {}

  @LogToServer()
  @LogToLocal()
  public backupWallet(backupMethod: string) {
    return {
      backupMethod,
    };
  }

  // Funnel numerator. Distinct from `backupWallet` (which fires when the user
  // picks a method) — this fires only when wallet.backuped flips true.
  @LogToServer()
  @LogToLocal()
  public backupCompleted(params: { walletId: string; walletType: string }) {
    return params;
  }

  // ---- Wallet backup-status migration diagnostics (local log only) ----
  // TODO(cleanup): temporary investigation scaffolding — remove these three
  // events and their ServiceAccount call sites once the backup-status
  // flag-loss root cause is fixed.
  // Investigating wallets flipping to "backed up" after an app restart:
  // migrateHdWalletsBackedUpStatus re-runs when the hdWalletsBackupMigrated
  // flag vanishes from storage between launches (suspected iOS AsyncStorage
  // key loss across the dual JS runtimes). These three events reconstruct
  // the full timeline from app-latest.log alone:
  //   1. backupMigrationStatusCheck  — on-disk truth at boot, before the
  //      migration decides to run or skip.
  //   2. backupMigrationMarkedWallets — the wallets the migration itself
  //      flipped to backed-up (no user action involved).
  //   3. backupMigrationFlagProbe — write-then-read-back verification after
  //      the flag write, and re-checks at later stages (e.g. after wallet
  //      creation) to narrow down when the flag disappears.

  @LogToLocal()
  public backupMigrationStatusCheck(params: {
    migratedFlag: boolean | undefined;
    appStatusRawExists: boolean;
    hdWalletsCount: number;
    unbackedUpHdWalletIds: string[];
  }) {
    return params;
  }

  @LogToLocal()
  public backupMigrationMarkedWallets(params: { walletIds: string[] }) {
    return params;
  }

  @LogToLocal()
  public backupMigrationFlagProbe(params: {
    stage: string;
    rawExists: boolean;
    flagPresent: boolean;
  }) {
    return params;
  }

  // Funnel denominator. Deduped to once per (wallet, state) tuple per session
  // by the caller.
  @LogToServer()
  @LogToLocal()
  public homePageViewed(params: {
    state: IHomePageViewedState;
    walletType: string;
  }) {
    return params;
  }

  @LogToServer()
  @LogToLocal()
  public enterManageToken() {}

  @LogToServer()
  @LogToLocal()
  public addCustomToken(token: IToken) {
    return token;
  }

  @LogToServer()
  @LogToLocal()
  public removeCustomToken(token: IToken) {
    return token;
  }

  @LogToServer()
  @LogToLocal()
  public walletManualRefresh() {}

  @LogToServer()
  @LogToLocal()
  public copyAddress(params: { walletType: 'hdWallet' | 'hwWallet' }) {
    return params;
  }

  @LogToServer()
  @LogToLocal()
  public openSidePanel() {}

  @LogToServer()
  @LogToLocal()
  public openExpandView() {}

  @LogToServer()
  @LogToLocal()
  public customNetworkAdded(params: {
    chainID: string;
    source?: 'manual' | 'chainList' | 'dapp';
  }) {
    return params;
  }

  @LogToLocal()
  public fetchNetworkFromServer() {
    return {};
  }

  @LogToLocal()
  public insertServerNetwork(networks: IServerNetwork[]) {
    return networks.map((network) => ({
      name: network.name,
      chainId: network.chainId,
    }));
  }

  @LogToLocal()
  public getServerNetworks(networks: IServerNetwork[]) {
    return networks.map((network) => ({
      name: network.name,
      chainId: network.chainId,
    }));
  }

  @LogToLocal()
  public getServerNetworksError(error: any) {
    let errorMessage = 'Unknown error';

    if (error instanceof Error) {
      errorMessage = error.message;
    } else if (typeof error === 'string') {
      errorMessage = error;
    } else if (error && typeof error === 'object') {
      errorMessage = JSON.stringify(error);
    }

    return {
      error: errorMessage,
    };
  }

  @LogToServer()
  @LogToLocal()
  public onboardingExit() {
    return {
      onboardingExit: true,
    };
  }

  @LogToLocal()
  @LogToServer()
  public walletPullToRefresh() {}
}
